<?php $pageTitle='Reservation received'; require __DIR__.'/partials/header.php'; $status=ns_status((string)$booking['status']); $nights=(new DateTimeImmutable($booking['check_in']))->diff(new DateTimeImmutable($booking['check_out']))->days; ?>
<main id="main" class="shell"><div class="receipt-wrap"><header class="receipt-heading"><div class="verification-symbol"><?= ns_icon('check') ?></div><p class="eyebrow" style="justify-content:center">Your next chapter starts here</p><h1>Reservation received.</h1><p>Thank you, <?= ns_e($booking['guest_name']) ?>. Your reservation has been recorded. Keep these details for your stay.</p></header><article class="receipt-card"><div class="receipt-card-top"><div><span class="label">Booking reference</span><strong class="receipt-reference">#<?= (int)$booking['id'] ?></strong></div><span class="status <?= $status ?>"><?= ns_e(ucfirst((string)$booking['status'])) ?></span></div><div class="receipt-body"><section class="receipt-stay"><p class="label">Your room</p><h2><?= ns_e($booking['room_title']) ?></h2><p class="receipt-duration"><?= $nights ?> <?= $nights===1?'night':'nights' ?> · <?= (int)$booking['num_guests'] ?> <?= (int)$booking['num_guests']===1?'guest':'guests' ?></p><dl class="receipt-dates"><div><dt class="label">Check-in</dt><dd><?= ns_e(ns_date($booking['check_in'])) ?></dd></div><div><dt class="label">Check-out</dt><dd><?= ns_e(ns_date($booking['check_out'])) ?></dd></div></dl><div class="receipt-guest"><h3>Guest information</h3><dl><?php foreach(['Name'=>'guest_name','Email'=>'guest_email','Phone'=>'guest_phone'] as $label=>$key): ?><div><dt><?= $label ?></dt><dd><?= ns_e($booking[$key]) ?></dd></div><?php endforeach; ?></dl></div></section><aside class="receipt-summary"><h2>Your stay at a glance</h2><div class="summary-row"><span>Room reservation</span><strong><?= $nights ?> nights</strong></div><div class="summary-row"><span>Guests</span><strong><?= (int)$booking['num_guests'] ?></strong></div><div class="receipt-total"><span class="label">Total room price</span><strong><span>NPR</span><?= ns_money($booking['total_price']) ?></strong></div><div class="receipt-note"><strong><?= $status==='pending'?'What happens next?':'Your reservation status' ?></strong><?= $status==='pending'?'Your reservation is awaiting confirmation. This receipt records your request and is not proof of payment.':'The status above reflects your reservation when this receipt was generated.' ?></div></aside></div><div class="receipt-bottom"><span>Save a copy of these details for your records.</span><button class="receipt-print" type="button" data-print-receipt><?= ns_icon('print') ?> Print / save receipt</button></div></article><div class="receipt-actions"><a class="button" href="<?= $isSignedIn?'/my-bookings':'/' ?>"><?= $isSignedIn?'My reservations':'Return to home' ?> <?= ns_icon('arrow') ?></a><a class="button button-outline" href="/rooms">Browse more rooms</a></div></div></main><?php require __DIR__.'/partials/footer.php'; ?>